CREATE TABLE IF NOT EXISTS credit_exchange_order_{{suffix}}(order_id varchar(128) COLLATE utf8mb4_bin PRIMARY KEY,user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,request_id varchar(128) COLLATE utf8mb4_bin NOT NULL,request_hash char(64) NOT NULL,admission_snapshot json NOT NULL,credit_cost decimal(18,2) NOT NULL CHECK(credit_cost>0),quota_snapshot json NOT NULL,business_at datetime(6) NOT NULL,business_date date NOT NULL,business_month char(7) NOT NULL,state varchar(16) NOT NULL CHECK(state IN ('DELIVERED','REJECTED')),receipt json NOT NULL,UNIQUE KEY request_identity(user_id,request_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS sign_in_order_{{suffix}}(order_id varchar(128) COLLATE utf8mb4_bin PRIMARY KEY,user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,business_date date NOT NULL,admission_snapshot json NOT NULL,business_at datetime(6) NOT NULL,state varchar(16) NOT NULL CHECK(state='DELIVERED'),receipt json NOT NULL,UNIQUE KEY daily(user_id,business_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS sign_in_reward_{{suffix}}(sign_in_order_id varchar(128) COLLATE utf8mb4_bin NOT NULL,reward_item_id varchar(64) COLLATE utf8mb4_bin NOT NULL,snapshot json NOT NULL,receipt json NOT NULL,PRIMARY KEY(sign_in_order_id,reward_item_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
